export interface ResolvedOfflineTile {
  z: number;
  x: number;
  y: number;
  scale: number;
  subX: number;
  subY: number;
}

export function hasOfflineTile(z: number, x: number, y: number): boolean {
  const xMap = OFFLINE_TILE_RANGES[z];
  if (!xMap) return false;
  const ranges = xMap[x];
  if (!ranges) return false;
  for (let i = 0; i < ranges.length; i++) {
    const [minY, maxY] = ranges[i];
    if (y >= minY && y <= maxY) return true;
  }
  return false;
}

/**
 * Finds the highest-resolution available local tile at or above (z, x, y)
 * in the Web Mercator quadtree pyramid (searching from min(z, 13) down to 4).
 */
export function resolveOfflineTile(
  targetZ: number,
  targetX: number,
  targetY: number,
  maxStartZ: number = 13
): ResolvedOfflineTile | null {
  const startZ = Math.min(targetZ, maxStartZ);
  for (let candZ = startZ; candZ >= 4; candZ--) {
    const scale = 1 << (targetZ - candZ);
    const candX = Math.floor(targetX / scale);
    const candY = Math.floor(targetY / scale);
    if (hasOfflineTile(candZ, candX, candY)) {
      return {
        z: candZ,
        x: candX,
        y: candY,
        scale,
        subX: targetX - candX * scale,
        subY: targetY - candY * scale,
      };
    }
  }
  return null;
}
